SELECT COUNT(*)
  FROM sys07_role_menu
 WHERE sys07_role_id IN (
           SELECT sys04_role_id
             FROM sys04_role
            WHERE sys04_company_id = #{companyId}
              AND sys04_role_nm = #{roleNm}
       )
   AND sys07_menu_id = #{menuId}

mapper.update:
UPDATE sys07_role_menu
   SET sys07_use_yn = (
           SELECT a.sys07_use_yn
             FROM sys07_role_menu a
            WHERE a.sys07_menu_id = #{menuId}
              AND a.sys07_role_id = (
                      SELECT sys04_role_id
                        FROM sys04_role
                       WHERE sys04_company_id = #{sourceCompanyId}
                         AND sys04_role_nm LIKE #{roleNm}
                  )
       )
 WHERE 1=1
   AND sys07_menu_id = #{menuId}
   AND sys07_role_id = (
           SELECT sys04_role_id
             FROM sys04_role
            WHERE sys04_company_id = #{companyId}
              AND sys04_role_nm LIKE #{roleNm}
       )

mapper.insert:
INSERT INTO sys07_role_menu
       (sys07_role_menu_id, sys07_role_id, sys07_menu_id, sys07_use_yn, sys07_note)
SELECT f_create_seq()
     , (
           SELECT sys04_role_id
             FROM sys04_role
            WHERE sys04_company_id = #{companyId}
              AND sys04_role_nm LIKE #{roleNm}
       )
     , a.sys07_menu_id
     , a.sys07_use_yn
     , a.sys07_note
  FROM sys07_role_menu a
 WHERE 1=1
   AND a.sys07_menu_id = #{menuId}
   AND a.sys07_role_id = (
           SELECT sys04_role_id
             FROM sys04_role
            WHERE sys04_company_id = #{sourceCompanyId}
              AND sys04_role_nm LIKE #{roleNm}
       )
